(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0101","batch":"03","category":"Categoria B","question":"Pe drumul public cu cel mult două benzi pe sens și cu o a treia bandă pe care este amplasată linia tramvaiului lângă axa drumului, conducătorii de vehicule:","answers":["Pot folosi banda pe care este amplasată linia tramvaiului, fără să incomodeze circulația acestuia","Nu pot folosi banda pe care este amplasată linia tramvaiului","Legal, nu este prevăzut"],"correctIndices":[0],"correct":0,"explanation":"Pe drumul public cu cel mult două benzi pe sens și cu o a treia bandă pe care este amplasată linia tramvaiului lângă axa drumului, conducătorii de vehicule pot folosi aceasta bandă, cu obligația să lase liberă calea tramvaiului la apropierea acestuia. Conducătorii de vehicule pot circula pe acea bandă atâta timp cât nu incomodează circulația tramvaiului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0101.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0101.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 101; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 100 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pe-drumul-public-cu-cel-mult-doua-benzi-pe-sens-si-cu-o-a-treia-banda-pe-care-este-amplasata-linia-tramvaiului-langa-axa-drumului-conducator","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"100","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0102","batch":"03","category":"Categoria B","question":"Există situații când conducătorul de autovehicul acordă prioritate de trecere bicicletei sau unui vehicul cu tracțiune animală?","answers":["Nu, legislația rutieră nu prevede asemenea situații","Nu, conducătorii de autovehicule au întotdeauna prioritate","Da"],"correctIndices":[2],"correct":2,"explanation":"Bicicliștii și conducătorii de vehicule cu tracțiune animală, ca și ceilalți participanți la trafic, trebuie să respecte regulile de circulație, indicatoarele, marcajele și semnalele polițistului rutier în aceeași măsură ca și autovehiculele. De exemplu, dacă un biciclist sau un conducător de vehicul cu tracțiune animală urmează să pătrundă într-o intersecție, venind de pe un drum prioritar, întâlnind indicatorul „Drum cu prioritate”, va avea prioritate față de autovehiculele care vin de pe drumurile fără prioritate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0102.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0102.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 102; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 101 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/exista-situatii-cand-conducatorul-de-autovehicul-acorda-prioritate-de-trecere-bicicletei-sau-unui-vehicul-cu-tractiune-animala","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"101","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0103","batch":"03","category":"Categoria B","question":"Se interzice circulația pe drumurile publice a autovehiculului dacă:","answers":["Mecanismul de direcție prezintă uzuri peste limitele admise","Autovehiculul are aplicate inscripții, desene, semne distinctive sau reclame de natură să împiedice ori să diminueze eficacitatea dispozitivelor de iluminare și de semnalizare luminoasă sau citirea numărului de înmatriculare","Autovehiculul are montate accesorii pe parbrize ori pe geamurile laterale, care restrâng sau estompează vizibilitatea conducătorului în timpul mersului"],"correctIndices":[0,1,2],"correct":0,"explanation":"Le este interzis conducătorilor de autovehicule să circule pe drumul public:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0103.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0103.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 103; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 102 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/se-interzice-circulatia-pe-drumurile-publice-a-autovehiculului-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"102","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0104","batch":"03","category":"Categoria B","question":"Cum procedează conducătorul de vehicul atunci când, apropiindu-se de o trecere la nivel cu calea ferată, prevăzută cu bariere ori semibariere, cele două lumini roșii funcționează intermitent-alternativ?","answers":["Continuă deplasarea, dacă barierele nu sunt coborâte","Oprește, deoarece barierele sunt închise sau urmează să coboare","Continuă deplasarea fără interdicție, deoarece luminile semnalizează doar prezența unei treceri la nivel cu calea ferată"],"correctIndices":[1],"correct":1,"explanation":"Atunci când vă apropiați de o trecere la nivel cu o cale ferată curentă prevăzută cu bariere sau semibariere și observați că cele 2 lumini roșii funcționează intermitent alternativ, aveți obligația de a opri, barierele fiind coborâte, în curs de coborâre sau de ridicare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0104.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0104.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 104; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 103 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedeaza-conducatorul-de-vehicul-atunci-cand-apropiindu-se-de-o-trecere-la-nivel-cu-calea-ferata-prevazuta-cu-bariere-ori-semibariere-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"103","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0105","batch":"03","category":"Categoria B","question":"În care dintre situații este interzisă staționarea voluntară a vehiculelor?","answers":["În dreptul căilor de acces care deservesc proprietățile alăturate drumurilor publice","În zona rezidențială semnalizată corespunzător","Pe drumurile județene"],"correctIndices":[0],"correct":0,"explanation":"Staționarea voluntară a vehiculelor este interzisă în dreptul căilor de acces care deservesc proprietățile alăturate drumurilor publice. Staționarea voluntară a vehiculelor este permisă, prin regulamentul rutier, în zona rezidențială semnalizată corespunzător. Staționarea voluntară a vehiculelor este permisă pe drumurile județene. Staționarea voluntară fiind interzisă pe partea carosabilă a autostrăzilor, a drumurilor expres și a celor naționale europene (E).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0105.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0105.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 105; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 104 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-este-interzisa-stationarea-voluntara-a-vehiculelor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"104","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0106","batch":"03","category":"Categoria B","question":"Ce se înțelege prin vigilență, din punct de vedere al conduitei preventive?","answers":["Capacitatea de a nu intra în conflict cu organele de poliție rutieră","Să fiți odihnit și bine alimentat, pentru a nu fi obligat să opriți pe traseu","Menținerea neîntreruptă a atenției pe toată durata deplasării"],"correctIndices":[2],"correct":2,"explanation":"Prin vigilență se înțelege menținerea neîntreruptă a atenției pe toată durata deplasării. Vigilența reprezintă capacitatea conducătorului auto de a observa atent și susținut, de a supraveghea continuu ceea ce se întâmplă în jurul său atunci când conduce autovehiculul, pentru a putea preveni un accident. Conducătorul auto trebuie să aibă atenția sporită și permanentă la tot ce se află și se petrece pe drum, la modul de funcționare a propriului vehicul, precum și la celelalte elemente de circumstanță, care pot fi întâlnite în traficul rutier. Atenția sporită nu trebuie să se manifeste ca o stare de încordare, de teamă de a nu greși, deoarece astfel se accentuează starea de oboseală sau stres. El trebuie să fie relaxat, dar nu excesiv detașat de ceea ce se întâmplă în jur, întrucât astfel scade atenția.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0106.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0106.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 106; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 105 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-se-intelege-prin-vigilenta-din-punct-de-vedere-al-conduitei-preventive","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"105","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0107","batch":"03","category":"Categoria B","question":"Cum trebuie să procedați atunci când autovehiculul derapează cu spatele către dreapta?","answers":["Frânați puternic și redresați vehiculul prin virare la stânga","Trageți rapid de volan spre stânga, fără a frâna","Eliberați pedala de accelerație și virați ușor spre dreapta"],"correctIndices":[2],"correct":2,"explanation":"Fenomenul se numește supravirare.În cazul supravirării anvelopele punții spate pierd aderența iar autovehiculul începe să se rotească în jurul axei verticale. Apariția supravirării apare cel mai des atunci când conducătorul frânează puternic în timpul virajului. Prin frânare, centrul de greutate al autovehiculului se deplasează către puntea din față, puntea spate se descarcă, iar roțile din spate pierd din aderență și derapează. Pentru a evita apariția supravirării, viteza de deplasare în timpul unui viraj trebuie să fie cât mai mică iar frânările bruște și intense să fie evitate. Se poate aplica o măsură de corecție a supravirării, numităcontravirare. Aceasta se realizează prin bracareaspre dreaptaa roților directoare. În acest mod se stopează rotirea autovechiculului în jurul axei verticale, deraparea punții spate fiind controlată. Prin urmare, în situația în care vehiculul derapează cu spatele către dreapta, se recomandă eliberarea pedalei de accelerație (accelerarea agravează situația de derapare) și rotirea ușoară a volanului spre dreapta.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0107.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0107.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 107; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 106 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-atunci-cand-autovehiculul-derapeaza-cu-spatele-catre-dreapta","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"106","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0108","batch":"03","category":"Categoria B","question":"Ce obligații aveți dacă, pe drumul pe care circulați, observați evenimente de natură a pune în pericol siguranța circulației?","answers":["Să semnalizați participanții la trafic care circulă din sens opus","Să emiteți semnale acustice","Să sesizați cea mai apropiată unitate de poliție în legătură cu obstacolele care pun în pericol siguranța circulației"],"correctIndices":[2],"correct":2,"explanation":"Participanții la trafic sunt obligați să anunțe administratorul drumului public ori cea mai apropiată unitate de poliție atunci când au cunoștință despre existența pe drum a unui obstacol sau a oricărei alte situații periculoase pentru fluența și siguranța circulației. Nu este obligatoriu să emiteți semnale acustice ori să semnalizați participanții la trafic care circulă din sens opus.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0108.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0108.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 108; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 107 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-daca-pe-drumul-pe-care-circulati-observati-evenimente-de-natura-a-pune-in-pericol-siguranta-circulatiei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"107","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0109","batch":"03","category":"Categoria B","question":"Victima care a pierdut mult sânge trebuie să fie așezată:","answers":["Cu fața în sus","Cu fața în jos","Cu picioarele situate mai sus decât nivelul corpului"],"correctIndices":[2],"correct":2,"explanation":"Victima care a pierdut mult sânge are presiunea arterială mică și trebuie să fie așezată pe spate, cu capul mai jos decât nivelul trunchiului și cu picioarele ridicate la circa 30 de cm pentru a facilita irigarea cu sânge a creierului. Hemoragia reprezintă sângele scurs dintr-un vas sanguin. În corpul uman cantitatea de sânge variază destul de mult depinzând de factori precum vârstă, sex, stare de sănătate, etc. Bărbații au mai mult sânge în corp decât femeile chiar dacă acestea au aceeași înălțime și greutate ca a bărbaților respectivi. Un adult cu o greutate medie, între 70 - 81 kg are între 4,7 - 5,5 litri de sânge iar un copil cu o greutate între 30 - 40 kg va avea aproximativ jumătate din cantitatea de sânge a unui adult. Gravitatea unei hemoragii se apreciază în funcție de cantitatea de sânge pierdut. Astfel în funcție de cantitatea sângelui pierdut hemoragia poate fi:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0109.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0109.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 109; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 108 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/victima-care-a-pierdut-mult-sange-trebuie-sa-fie-asezata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"108","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0110","batch":"03","category":"Categoria B","question":"Termostatul aparține instalației de:","answers":["Răcire","Ungere","Alimentare"],"correctIndices":[0],"correct":0,"explanation":"Termostatul face parte din instalația de răcire a unui motor cu ardere internă și reglează circulația lichidului de răcire pentru a menține temperatura optimă de funcționare. Când motorul este rece după pornire, termostatul rămâne închis, împiedicând lichidul de răcire să ajungă în radiator, astfel încât motorul să se încălzească mai rapid. După atingerea temperaturii optime, termostatul se deschide, permițând lichidului să circule prin radiator pentru a preveni supraîncălzirea. Temperatura lichidului de răcire care asigură performanța maximă, un consum redus de combustibil și uzura minimă a motorului este cuprinsă în intervalul 90-95 grade Celsius. Circulația frecventă cu termostatul defect și cu o temperatură a lichidului de răcire sub 60 grade Celsius, conduce la creșterea consumului de combustibil cu 30 până la 90 %.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0110.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0110.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 110; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 109 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/termostatul-apartine-instalatiei-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"109","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0111","batch":"03","category":"Categoria B","question":"Indicatorul interzice:","answers":["Oprirea din dreptul lui până la prima intersecție","Staționarea din dreptul lui până la prima intersecție","Oprirea pe o distanță de 50 m de la locul în care este instalat"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul din imagine se numește “Staționarea interzisă”, acest indicator interzice staționarea voluntară a vehiculelor, zona acestuia de acțiune încetează la cel mai apropiat colț de intersecție pe sensul de mers, dar poate fi însoțit și de alte panouri adiționale care marchează începutul, continuarea sau sfârșitul zonei de acțiune (Începutul zonei de acțiune a indicatorului, Confirmarea zonei de acțiune a indicatorului și Sfârșitul zonei de acțiune a indicatorului) sau poate avea aplicate, direct pe panoul indicatorului, inscripții cu aceeași semnificație. Indicatorul mai poate fi însoțit și de panoul adițional „Săgeată cu vârful în sus” care semnifică începutul zonei de acțiune și distanța de acțiune a indicatorului, exprimată în metri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0111.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0111.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 111; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă perspectiva unui șofer, aflat pe un drum urban cu mai multe benzi. Indicatorul circular albastru, cu margine roșie și o singură linie roșie, dungată, care interzice staționarea vehiculelor până la prima intersecție, este vizibil pe partea dreaptă a drumului.","needsImageReview":true,"source":"RoDrive · ID 110 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-interzice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"110","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_112.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0112","batch":"03","category":"Categoria B","question":"Care este semnificația indicatorului?","answers":["Obligă la ocolirea prin dreapta a locului unde este instalat","Obligă la schimbarea direcției de mers către dreapta","Obligă la folosirea benzii de lângă trotuar"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul se numește “Ocolire”, acesta se instalează înaintea unui obstacol pe partea carosabilă, pe care conducătorul auto este obligat să îl ocolească în sensul indicat de săgeată. În situația dată ocolirea obstacolului se face prin partea dreaptă. Trebuie să ținem cont că în lipsa unui indicator care să ne oblige la ocolire printr-o anumită direcție, așa cum este indicatorul din imagine, ocolirea obstacolelor din zona mediană se va face prin partea dreaptă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0112.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0112.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 112; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular albastru, cu o săgeată albă în direcția dreapta-jos, arată direcția obligatorie de ocolire pe partea dreaptă.","needsImageReview":true,"source":"RoDrive · ID 111 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-semnificatia-indicatorului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"111","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_113.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0113","batch":"03","category":"Categoria B","question":"Este interzisă staționarea pe un drum public prevăzut cu marcaj longitudinal continuu aplicat între sensurile de circulație?","answers":["Nu, dacă nu obligă celelalte vehicule să treacă peste marcajul continuu","Nu există prevedere legală","Da, deoarece este interzis prin lege"],"correctIndices":[0],"correct":0,"explanation":"Se interzice staționarea voluntară a vehiculelor în toate cazurile în care oprirea voluntară este interzisă, iar oprirea voluntară este interzisă în dreptul marcajului continuu, atunci când conducătorii celorlalte vehicule care circulă în același sens sunt obligați din această cauză sa încalce marcajul continuu. Dar în situația în care prin staționare nu îi obligă pe conducătorii celorlalte vehicule care circulă în același sens să încalce marcajul continuu de separare a sensurilor de circulație,manevra de staționare este regulamentară, ca de exemplu pe un drum foarte lat sau pe un drum cu două sau mai multe benzi de circulație pe sens, unde, prin manevra de staționare, ceilalți conducători de vehicule nu sunt obligați din această cauză sa încalce marcajul continuu.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0113.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0113.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 113; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum urban cu mai multe benzi de circulație. Marcajele longitudinale cu linie discontinuă indică separarea benzilor, fiind câte două benzi pentru fiecare sens de mers. Marcajul longitudinal continuu din mijloc interzice depășirea vehiculelor pe sens opus. Este suficient spațiu pentru staționarea unui vehicul pentru a nu stânjeni traficul.","needsImageReview":true,"source":"RoDrive · ID 112 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-interzisa-stationarea-pe-un-drum-public-prevazut-cu-marcaj-longitudinal-continuu-aplicat-intre-sensurile-de-circulatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"112","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_114.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0114","batch":"03","category":"Categoria B","question":"Oprirea este interzisă:","answers":["La mai puțin de 50 m de colțul intersecției","În locul în care se împiedică vizibilitatea unui semnal luminos","În curbe cu vizibilitatea sub 100 m"],"correctIndices":[1],"correct":1,"explanation":"Este permisăoprirea la mai puțin de 50 de metri de colțul unei intersecții, deoarece oprirea se interzice în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestora la mai puțin de 25 de metri de colțul intersecției. Oprirea voluntară a vehiculelor este interzisă în locurile unde s-ar împiedica observarea unui indicator sau semnal luminos. Oprirea este interzisă în curbele cu vizibilitatea sub 50 de metri, nu în curbele cu vizibilitate sub 100 de metri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0114.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0114.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 114; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 113 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"113","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0115","batch":"03","category":"Categoria B","question":"La ce distanță de trecerea la nivel cu calea ferată sunt instalate panourile suplimentare de avertizare?","answers":["Primul la 90 m, al doilea la 60 m și al treilea la 30 m","Primul la 200 m, al doilea la 150 m și al treilea la 100 m","Primul la 150 m, al doilea la 100 m și al treilea la 50 m"],"correctIndices":[2],"correct":2,"explanation":"Trecerea la nivel cu calea ferată curentă este presemnalizată cu panouri suplimentare pentru avertizarea apropierii de o trecere la nivel cu o cale ferată, acestea sunt montate de o parte și de cealaltă a trecerii la nivel cu calea ferată, după cum urmează: La întâlnirea indicatorului cu trei linii, conducătorul auto este obligat să reducă viteza. La întâlnirea ultimului indicator, cel cu o singură linie, conducătorul auto nu mai are voie să execute nicio manevră (depășirea, oprirea, staționarea, mersul înapoi, întoarcerea). In oraș, din cauza condițiilor de trafic, sunt situații în care se găsește instalat numai cel de-al treilea panou, cel cu o singură linie.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0115.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0115.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 115; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 114 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-ce-distanta-de-trecerea-la-nivel-cu-calea-ferata-sunt-instalate-panourile-suplimentare-de-avertizare","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"114","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0116","batch":"03","category":"Categoria B","question":"Tensiunea nervoasă și oboseala conducătorului auto pot fi reduse dacă:","answers":["Rulați cu o viteză ponderată, în condiții de siguranță, menținând un ritm de mers constant","Circulați cu aceeași viteză atât în localități, cât și în afara acestora","Folosiți medicamente calmante sau energizante care nu sunt interzise conducătorilor auto"],"correctIndices":[0],"correct":0,"explanation":"Oboseala și tensiunea nervoasă a conducătorului auto pot fi reduse dacă se rulează cu o viteză ponderată, în condiții de siguranță, menținând un ritm de mers cât mai constant. În interiorul localităților, limita maximă de viteză fiind, în general, de 50 de km/h, nu puteți circula cu viteza din afara localităților, unde limita maximă de viteză este de 90, 100, 120 sau 130 de km/h. Iar invers, să circulați în afara localităților cu aceeași viteză cu care circulați în localități, nu se recomandă, deoarece i-ați obliga pe ceilalți participanți la trafic să vă depășească, fapt care vă va solicita și mai mult, parcurgerea drumului ar dura mai mult și starea de oboseală se va agrava. Utilizarea medicamentelor calmante sau energizante, chiar dacă nu sunt interzise conducătorilor auto, nu contribuie la reducerea oboselii și a tensiunii nervoase. Medicamentele calmante pot accentua starea de oboseală, în timp ce cele energizante pot amplifica starea de nervozitate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0116.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0116.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 116; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 115 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/tensiunea-nervoasa-si-oboseala-conducatorului-auto-pot-fi-reduse-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"115","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0117","batch":"03","category":"Categoria B","question":"Cum procedați în situația în care observați în fața dvs. o minge care se rostogolește?","answers":["Continuați să circulați cu aceeași viteză, întrucât trecerea peste minge nu este periculoasă pentru autovehicul","Semnalizați sonor, reduceți viteza și circulați cu maximă atenție, întrucât este foarte posibil să apară un copil după minge","Virați brusc în direcția opusă de rostogolire a mingii"],"correctIndices":[1],"correct":1,"explanation":"Atunci când observați în fața dumneavoastră o minge care se rostogolește, trebuie să reduceți imediat viteza, să circulați cu maximă atenție și să vă pregătiți pentru frânare, întrucât este foarte posibil să apară un copil după aceasta, care să se angajeze pe partea carosabilă fără să se asigure. Se recomandă să semnalizați sonor, chiar dacă nu observați un copil care are intenția de a veni după minge.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0117.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0117.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 117; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 116 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-in-care-observati-in-fata-dvs-o-minge-care-se-rostogoleste","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"116","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0118","batch":"03","category":"Categoria B","question":"În care dintre situații este interzis să circulați pe drumurile publice?","answers":["Atunci când certificatul de înmatriculare este deteriorat","Atunci când vehiculul nu este asigurat de răspundere civilă, în caz de pagube materiale produse terților prin accidente de circulație, conform legii","Atunci când conducătorul auto nu a plătit taxa de folosire a drumurilor publice"],"correctIndices":[1],"correct":1,"explanation":"În cazul în care certificatul de înmatriculare sau înregistrare este deteriorat, NU vă este interzis să circulați pe drumurile publice, dar aveți obligația ca în termen de cel mult 30 de zile de la data constatării deteriorării sa cereți eliberarea unui nou certificat de înmatriculare sau înregistrare. Este interzisă circulația pe drumurile publice a vehiculului care nu are încheiată asigurarea de răspundere civilă, în caz de pagube materiale produse terților prin accidente de circulație (RCA). Taxa de folosire a drumurilor nu se percepe pe toate categoriile de drumuri, deci se poate circula pe drumurile pe care nu se percepe taxă de folosire a acestora, ca de exemplu în interiorul reședințelor de Județ sau a Municipiilor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0118.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0118.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 118; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 117 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-este-interzis-sa-circulati-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"117","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0119","batch":"03","category":"Categoria B","question":"Ce trebuie să faceți pentru evitarea complicațiilor în cazul unei fracturi?","answers":["Să imobilizați zona fracturată","Să sterilizați și să pansați zona fracturată","Să aplicați un garou de cauciuc deasupra fracturii"],"correctIndices":[0],"correct":0,"explanation":"În cazul unei fracturi se impune imobilizarea provizorie a acesteia cu ajutorul atelelor, care trebuie sa fie suficient de lungi pentru a fixa atât articulația de deasupra, cât și cea de dedesubtul osului rupt. În cazul unei fracturi cervicale, imobilizați gâtul cu un prosop rulat, cu diametru de aproximativ 10 cm, strâns lejer în jurul gâtului, având grijă ca legătura să nu stânjenească respirația, victima va fi așezată pe o targă tare (scândură, ușă), suficient de lungă și de lată, în așa fel încât corpul să nu se îndoaie sau să se miște lateral. Sterilizarea se impune în cazul unei plăgi. O fractură poate fi deschisă (cu rană) sau închisă (fără rană), prin urmare sterilizarea și pansarea se impune doar în cazul unei fracturi deschise, nu pentru orice tip de fractură. Aplicarea unui garou, numai atunci când gravitatea hemoragiei pune în pericol viața victimei și când sângerarea nu poate fi oprită prin alte mijloace. Garoul se așază întotdeauna deasupra rănii, între rană și corp, dar fără a atinge rana.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0119.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0119.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 119; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 118 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-trebuie-sa-faceti-pentru-evitarea-complicatiilor-in-cazul-unei-fracturi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"118","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0120","batch":"03","category":"Categoria B","question":"Indicatorul din imagine vă avertizează că urmează:","answers":["O succesiune de curbe pe o distanță de 1,5 km, prima curbă fiind la stânga","O succesiune de curbe în rampă la o distanță de 1,5 km față de indicator, prima curbă fiind la dreapta","O curbă dublă, prima la dreapta, la o distanță de 1,5 km față de indicator"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul din imagine se numește „Curbă dublă sau o succesiune de mai mult de două curbe, prima la stânga” și vă avertizează ca urmează o curbă dublă sau o succesiune de curbe dintre care prima fiind către stânga. Iar panoul adițional se numește „Lungimea sectorului periculos la care se referă indicatorul” și are rolul de a preciza lungimea sectorului de drum periculos la care se referă indicatorul împreună cu care este montat pe drumurile publice. Prin urmare, indicatorul din imagine vă avertizează că urmează o succesiune de curbe pe o distanţă de 1,5 km, prima curbă fiind la stânga.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0120.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0120.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 120; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum cu semafor și un indicator triunghiular cu margini roșii cu simbolul unor succesiuni de curbe, care este însoțit de un panou adițional pe care scrie 1.5km, având în stânga și în dreapta săgeți negre, direcționate în sus, ce simbolizează începutul zonei marcate de indicator.","needsImageReview":true,"source":"RoDrive · ID 119 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-din-imagine-va-avertizeaza-ca-urmeaza","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"119","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_121.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0121","batch":"03","category":"Categoria B","question":"Semnalul verde al semaforului vă permite:","answers":["Să circulați pe direcția înainte sau la stânga","Să circulați în orice direcție","Să circulați pe direcția înainte sau la dreapta"],"correctIndices":[2],"correct":2,"explanation":"Atunci când urmează să pătrundeți într-o intersecție la culoarea verde a semaforului trebuie să respectați și semnificația indicatoarelor instalate la intrarea în intersecție, cu excepția indicatoarelor de reglementare de prioritate care se vor respecta doar atunci când semafoarele nu funcționează sau atunci când semafoarele au în funcțiune semnalul cu lumină de culoare galbenă intermitentă. În această situație întâlniți indicatorul „Înainte sau la dreapta” iar semaforul se află pe culoarea verde. În acest caz obligația de a respecta și semnificația indicatorului de obligare. Prin urmare veți circula doar pe direcțiile înainte sau la dreapta, virajul către stânga fiind interzis.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0121.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0121.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 121; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată, cu semafor verde pentru direcția înainte. Indicatorul adițional arată că drumul are prioritate.","needsImageReview":true,"source":"RoDrive · ID 120 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-verde-al-semaforului-va-permite","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"120","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_122.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0122","batch":"03","category":"Categoria B","question":"Este permisă folosirea luminilor de ceață noaptea, dacă cerul este senin?","answers":["Regulamentul nu precizează","Da","Nu"],"correctIndices":[2],"correct":2,"explanation":"Conducătorul de autovehicul este obligat ca pe timp de ceață densă să folosească luminile de întâlnire și luminile de ceață, indiferent dacă circulă pe timp de zi sau de noapte. Se interzice folosirea luminilor de ceață în lipsa ceții (atunci când cerul este senin), indiferent dacă se circulă pe timp de zi sau de noapte. Folosirea luminilor de ceață în alte condiții decât pe timp de ceață constituie contravenție și se sancționează cu amendă prevăzută în clasa a doua de sancțiuni și cu aplicarea a 3 puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0122.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0122.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 122; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum în condiții de vizibilitate redusă (seară).","needsImageReview":true,"source":"RoDrive · ID 121 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-folosirea-luminilor-de-ceata-noaptea-daca-cerul-este-senin","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"121","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_123.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0123","batch":"03","category":"Categoria B","question":"Cum trebuie să procedați corect, dacă vă aflați la volanul autoturismului?","answers":["Permiteți trecerea camionului","Permiteți trecerea tramvaiului","Virați înaintea tramvaiului"],"correctIndices":[1],"correct":1,"explanation":"Intersecția din imagine este dirijată prin indicatoare de reglementare de prioritate. Dumneavoastră, aflându-vă la volanul autoturismului, circulați pe drumul cu prioritate, asemenea tramvaiului. Însă dumneavoastră trebuie să îi acordați tramvaiului prioritate de dreapta deoarece, virând către stânga, tramvaiul vă vine din partea dreaptă. Autocamionul trebuie să vă acorde prioritate de trecere deoarece întâlnește indicatorul „Oprire”. Prin urmare, trebuie să îi permiteți trecerea tramvaiului, după care puteți traversați intersecția.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0123.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0123.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 123; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată în care vehiculul roșu vine din stânga, virează la stânga și are indicator de prioritate, iar tramvaiul și vehiculul albastru circulă înainte. Tramvaiul vine din dreapta și are indicator de prioritare, iar autocamionul vine de jos, vrea să meargă înainte și are indicatorul octogonal STOP.","needsImageReview":true,"source":"RoDrive · ID 122 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-corect-daca-va-aflati-la-volanul-autoturismului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"122","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_124.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0124","batch":"03","category":"Categoria B","question":"Lumina galbenă intermitentă instalată în zona trecerilor pentru pietoni vă obligă la:","answers":["Reducerea vitezei, având grijă să feriți pietonii care traversează","Reducerea vitezei și folosirea luminii farurilor, pentru avertizarea pietonilor care intenționează să se angajeze în traversare","Reducerea vitezei și respectarea semnalizării și a regulilor de circulație aplicabile în acea zonă"],"correctIndices":[2],"correct":2,"explanation":"Semnalul de culoare galben intermitent obligă la reducerea vitezei de deplasare și respectarea semnificației semnalizării rutiere aplicabile în acel loc. Deci la întâlnirea acestui semnal, instalat în zona trecerilor pentru pietoni, veți reduce viteza de deplasare și veți acorda prioritate de trecere pietonilor care intenționează să traverseze pe trecerea pentru pietoni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0124.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0124.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 124; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 123 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/lumina-galbena-intermitenta-instalata-in-zona-trecerilor-pentru-pietoni-va-obliga-la","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"123","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0125","batch":"03","category":"Categoria B","question":"Care este viteza maximă prevăzută de lege pentru circulația în zonele rezidențiale?","answers":["5 km/h","10 km/h","20 km/h"],"correctIndices":[2],"correct":2,"explanation":"În zonele rezidențiale semnalizate ca atare aveți obligația să circulați cu o viteză de cel mult 20 de km/h și să nu staționați sau să parcați autovehiculul în afara spațiilor special destinate și semnalizate. Zona rezidențială este semnalizată la intrare cu indicatorul „Zonă rezidențială” iar la ieșire cu indicatorul „Sfârșitul zonei rezidențiale”.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0125.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0125.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 125; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 124 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-viteza-maxima-prevazuta-de-lege-pentru-circulatia-in-zonele-rezidentiale","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"124","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0126","batch":"03","category":"Categoria B","question":"Într-o intersecție întâlniți semnalul de culoare verde al semaforului, precum și indicatorul „Oprire“. Cum veți proceda?","answers":["Respectați semnificația indicatorului rutier","Respectați semnificația culorii semaforului","Circulați cu atenție și acordați prioritate de trecere vehiculelor de pe drumul transversal"],"correctIndices":[1],"correct":1,"explanation":"Participanții la trafic au obligația de a respecta semnalele luminoase cu prioritate față de indicatoarele de reglementare de prioritate. Prin urmare, în situația dată se va respecta semnificația semnalului semaforului. Semnificația indicatoarelor de reglementare de prioritate instalate lângă semafoare se va respecta doar în situația în care semafoarele nu funcționează sau funcționează pe culoarea galbenă intermitentă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0126.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0126.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 126; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 125 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intr-o-intersectie-intalniti-semnalul-de-culoare-verde-al-semaforului-precum-si-indicatorul-oprire-cum-veti-proceda","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"125","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0127","batch":"03","category":"Categoria B","question":"Care dintre conducătorii de vehicule, ce se apropie simultan de o intersecție, are prioritate de trecere, în situația în care unul întâlnește indicatorul „Oprire”, iar celălalt indicatorul „Cedează trecerea”?","answers":["Conducătorul care întâlnește indicatorul „cedează trecerea“","Conducătorul care circulă din dreapta","Conducătorul care întâlnește indicatorul „oprire“"],"correctIndices":[1],"correct":1,"explanation":"Într-o intersecție dirijată prin indicatoare de reglementare de prioritate vor să pătrundă simultan doi conducători de vehicule, unul întâlnind indicatorul „Oprire” iar celălalt indicatorul „Cedează trecerea”, iar traiectoriile acestora prin intersecție se intersectează. Aceste indicatoare au același grad de prioritate, mai exact ambele fiind de pierdere de prioritate. Între cei doi conducători s-a creat o situație de egalitate, ambii conducători venind de pe drumuri pe care se găsesc instalate indicatoare de pierdere de prioritate. Între aceștia se va aplica regula priorității de dreapta, caz în care vehiculul care vine din partea dreaptă are prioritate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0127.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0127.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 127; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 126 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-conducatorii-de-vehicule-ce-se-apropie-simultan-de-o-intersectie-are-prioritate-de-trecere-in-situatia-in-care-unul-intalneste-i","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"126","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0128","batch":"03","category":"Categoria B","question":"Vă este permis să parcați vehiculul pe drumurile publice:","answers":["În locurile special amenajate și semnalizate prin indicatoare și marcaje rutiere","Acolo unde nu există parcări amenajate","Acolo unde circulația în ambele sensuri se desfășoară fără dificultate"],"correctIndices":[0],"correct":0,"explanation":"Se consideră parcare, staționarea vehiculelor în spații special amenajate sau stabilite și semnalizate corespunzător. Prin urmare, parcarea nu este permisă în alte locuri decat în cele special amenajate și semnalizate prin indicatoare și marcaje rutiere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0128.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0128.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 128; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 127 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/va-este-permis-sa-parcati-vehiculul-pe-drumurile-publice","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"127","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0129","batch":"03","category":"Categoria B","question":"Pe o autostradă cu trei benzi, s-a blocat circulația. Pe unde vor circula vehiculele de intervenție?","answers":["Pe banda de urgență","Între banda din stânga și banda din mijloc","Între banda din dreapta și banda din mijloc"],"correctIndices":[0],"correct":0,"explanation":"În situațiile în care autostrada este blocată, vehiculele cu regim de circulație prioritară care se deplasează la intervenții vor circula pe banda de urgență. De aceea pe autostradă este interzisă circulația, oprirea sau staționarea pe banda de urgență, cu excepția cazurilor justificate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0129.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0129.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 129; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 128 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/pe-o-autostrada-cu-trei-benzi-s-a-blocat-circulatia-pe-unde-vor-circula-vehiculele-de-interventie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"128","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0130","batch":"03","category":"Categoria B","question":"Care este cea mai vulnerabilă categorie de participanți la trafic, din rândul căreia se înregistrează cele mai multe victime?","answers":["Conducătorii de vehicule fără experiență în conducere","Conducătorii de vehicule cu atestat profesional","Pietonii, îndeosebi copiii și persoanele în vârstă"],"correctIndices":[2],"correct":2,"explanation":"Cea mai vulnerabilă categorie de participanți la trafic, din rândul căreia se înregistrează cele mai multe victime, sunt pietonii, deoarece în cazul unui accident aceștia nu au nici un sistem de protecție, îndeosebi copiii și persoanele în vârstă. Copii nu își dau seama de riscul la care se expun și nu sunt atenți în trafic, iar persoanele în vârstă pentru că au o viteză mică de reacție. Conducătorii de vehicule fără experiență în conducere și conducătorii de vehicule cu atestat profesional au, în majoritatea cazurilor, sisteme de protecție în caz de accident foarte performante, ceea ce face ca aceștia să nu fie atât de vulnerabili cum sunt pietonii.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0130.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0130.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 130; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 129 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-cea-mai-vulnerabila-categorie-de-participanti-la-trafic-din-randul-careia-se-inregistreaza-cele-mai-multe-victime","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"129","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0131","batch":"03","category":"Categoria B","question":"Copiii cu vârste de până la 12 ani pot fi transportați:","answers":["Pe scaunul din față al autovehiculului, dacă sunt ținuți în brațe de persoane majore","Pe scaunul din față al autovehiculului, având fixată centura de siguranță","Pe bancheta din spate a autovehiculului, având fixată centura de siguranță, adaptată greutății și dimensiunilor lor"],"correctIndices":[2],"correct":2,"explanation":"În legislația actualizată s-au făcut modificări cu privire la transportul copiilor, printre care s-a eliminat și limita de vârstă de 12 ani. Dar dacă luăm ca exemplu un copil cu vârsta de sub 12 ani, acesta va putea fi transportatfără dispozitiv de fixare în scaun pentru copii, dar cu centura de siguranță pentru adulți, reglată astfel încât să nu treacă peste zona gâtului sau feței,doar dacă are o înălțime de peste 135 de cm.În cazul în care acesta are o înălțime până la 135 de cm, obligatoriu se va transporta numai îndispozitiv de fixare în scaun pentru copii. Legislația rutieră impune reguli stricte pentru transportul copiilor în autovehicule, incluzând obligații speciale pe care conducătorii auto trebuie să le cunoască și să le respecte. Pentru detalii complete, accesați cursul de legislație VIDEO din pasul 1, unde găsiți o lecție dedicată transportului copiilor, explicată în format video -Obligații și interdicții privind transportul copiilor.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0131.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0131.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 131; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 130 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/copiii-cu-varste-de-pana-la-12-ani-pot-fi-transportati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"130","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0132","batch":"03","category":"Categoria B","question":"Consumul de carburant se mărește dacă:","answers":["Lichidul de răcire nu conține antigel","Sistemul de direcție este manual","Folosiți orice aparat electric alimentat de generatorul autovehiculului"],"correctIndices":[2],"correct":2,"explanation":"Lipsa de antigel în lichidul de răcire nu cauzează creșterea consumului de carburant, acesta este adăugat pentru a împiedica înghețarea lichidului de răcire pe timp de iarnă. Dacă sistemul de direcție este manual, înseamnă că nu are în componență alte mecanisme electrice sau hidraulice, nu are impact asupra consumului de carburant. Aparatele electrice alimentate de generatorul autovehiculului (de alternator) cresc consumul de carburant. Alternatorul este componenta principală a sistemului de generare de curent electric al automobilului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0132.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0132.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 132; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 131 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/consumul-de-carburant-se-mareste-daca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"131","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0133","batch":"03","category":"Categoria B","question":"Cum se definește corect autovehiculul din categoria B?","answers":["Autovehiculul care nu depășește 5.000 kg, al cărui număr de locuri pe scaune, în afara conducătorului, este mai mic de 8","Autovehiculul care nu depășește 3.500 kg, al cărui număr de locuri pe scaune, în afara conducătorului, nu este mai mare de 8","Autovehiculul care nu depășește 3.500 kg, al cărui număr de locuri pe scaune, în afara conducătorului, nu este mai mare de 5"],"correctIndices":[1],"correct":1,"explanation":"Autovehiculul din categoria B este acel autovehicul a cărui masă totală maximă autorizată (MTMA) nu depășește 3.500 kg și al cărui număr de locuri pe scaune, în afara conducătorului, nu este mai mare de 8.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0133.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0133.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 133; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 132 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-se-defineste-corect-autovehiculul-din-categoria-b","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"132","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0134","batch":"03","category":"Categoria B","question":"Ce măsuri de precauție trebuie să luați la utilizarea soluției antigel?","answers":["Nicio măsură, întrucât lichidul respectiv nu este nociv","Se va evita contactul cu aceasta, deoarece este toxică","Nu se va combina cu apa, deoarece degajă multă căldură"],"correctIndices":[1],"correct":1,"explanation":"La utilizarea soluției antigel trebuie să fiți extrem de precauți și să evitați contactul cu aceasta, deoarece este toxică. Înghițirea a 100 ml de soluție antigel este mortală. Soluția antigel coboară punctul de îngheț al apei de răcire din motoarele cu ardere internă, aceasta se diluează cu apă, formând astfel lichidul de răcire al motorului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0134.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0134.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 134; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 133 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-masuri-de-precautie-trebuie-sa-luati-la-utilizarea-solutiei-antigel","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"133","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0135","batch":"03","category":"Categoria B","question":"Ce semnificație are marcajul rutier din imagine?","answers":["Bandă de circulație destinată opririi voluntare","Spațiu pentru oprirea în caz de urgență","Marcaj transversal de oprire"],"correctIndices":[2],"correct":2,"explanation":"Marcajul rutier din imagine este un marcaj transversal pentru oprire, acesta indică linia înaintea căreia vehiculul trebuie oprit la întâlnirea indicatorului \"Oprire\", acest marcaj poate fi întâlnit și împreună cu marcajul „STOP”, ca în exemplul din imagine. La întâlnirea acestui marcaj conducătorul de vehicul este obligat să oprească înainte de linia orizontală continuă, indiferent dacă pe drumul prioritar circulă sau nu alte vehicule, dacă circulă vehicule pe drumul prioritar le acordă prioritate, după care își poate continua deplasarea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0135.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0135.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 135; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă marcajele rutiere specifice unei intersecții. Pe drumul perpendicular cu drumul principal, se află un marcaj transversal pe bandă, cu o linie perpendiculară cu banda și scrisul 'STOP' înainte de linie.","needsImageReview":true,"source":"RoDrive · ID 134 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnificatie-are-marcajul-rutier-din-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"134","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_137.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0136","batch":"03","category":"Categoria B","question":"Folosirea incorectă, pe timp de noapte, a luminilor de drum la întâlnirea cu alt autovehicul care circulă din sens opus, se sancționează cu:","answers":["Suspendarea exercitării dreptului de a conduce autovehicule, dacă această contravenție a fost săvârșită în mod repetat","Anularea permisului de conducere","Amendă și puncte de penalizare"],"correctIndices":[2],"correct":2,"explanation":"Se poate suspenda exercitarea dreptului de a conduce autovehicule, pe o perioadă de 30 de zile, în cazul în care se acumulează cel puțin 15 puncte de penalizare. Pentru a acumula cel puțin 15 puncte de penalizare este nevoie să fiți sancționat de 8 ori pentru această contravenție. Dar în varianta A nu se specifică nici perioada de suspendare, nici numărul de repetări ale acestei sancțiuni. Prin urmare varianta A nu poate fi corectă. Anularea permisului de conducere nu se aplică pentru această contravenție. Când circulați pe timpul nopții, la apropierea de un alt vehicul care circulă din sens opus (vine din sens opus spre vehiculul pe care îl conduceți), sunteți obligat ca de la distanța de cel puțin 200 de metri să folosiți luminile de întâlnire, concomitent cu reducerea vitezei. În cazul în care în acel moment circulați cu luminile de drum (faza lungă) în funcțiune, trebuie să le schimbați cu luminile de întâlnire (faza scurtă), pentru a nu-i deranja pe cei din față, concomitent cu reducerea vitezei de deplasare. Nerespectarea acestei obligații, circulând cu faza de drum, se sancționează cu amendă contravențională prevăzută în clasa I de sancțiuni și cu aplicarea a două puncte de penalizare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0136.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0136.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 136; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 135 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/folosirea-incorecta-pe-timp-de-noapte-a-luminilor-de-drum-la-intalnirea-cu-alt-autovehicul-care-circula-din-sens-opus-se-sanctioneaza-cu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"135","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0137","batch":"03","category":"Categoria B","question":"Ce obligații aveți în situația prezentată în imagine?","answers":["Să nu depășiți alte vehicule","Să reduceți viteza","Să opriți la 50 m de calea ferată"],"correctIndices":[1],"correct":1,"explanation":"Vă este permis să depașiți alte vehicule la distanța de 150 de metri de trecerea la nivel cu calea ferată, deoarece depășirea este interzisă la mai puțin de 50 de metri de trecerea la nivel cu calea ferată. Indicatorul din imagine vă avertizează ca la 150 de metri urmează o trecere la nivel cu o cale ferată curentă, iar la trecerile la nivel cu calea ferată curentă aveți obligația de a reduce viteza de deplasare și să vă asigurați că din partea dreaptă sau din partea stângă nu se apropie un vehicul feroviar. Vă este permis să opriți la distanța de 150 de metri de trecerea la nivel cu calea ferată, deoarece oprirea este interzisă la mai puțin de 50 de metri de trecerea la nivel cu calea ferată.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0137.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0137.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 137; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator triunghiular roșu, cu un gard negru în mijlocul său, care avertizează că se află o trecere la nivel cu calea ferată semnalizată cu bariere. Panoul adițional, dreptunghiular cu trei linii roșii oblice, una sub alta arată că trecerea este la 150 metri distanță.","needsImageReview":true,"source":"RoDrive · ID 136 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-aveti-in-situatia-prezentata-in-imagine","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"136","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_139.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0138","batch":"03","category":"Categoria B","question":"Cum procedați în situația dată?","answers":["Acordați prioritate autoturismului din stânga","Vă continuați drumul","Acordați prioritate autoturismului din dreapta"],"correctIndices":[1],"correct":1,"explanation":"În această intersecție întâlniți indicatorul „Drum cu prioritate” însoțit de un panou adițional care indică direcția drumului cu prioritate, deci dvs. circulați pe drumul cu prioritate. Celelalte autoturisme au obligația de a va acorda prioritate de trecere. Autoturismul din dreapta vine de pe un drum fără prioritate și trebuie să acorde prioritate vehiculelor care vin de pe drumul cu prioritate, iar autoturismul care circulă din partea stângă vine de pe un drum cu prioritate, asemenea dvs., însă acesta, părăsind drumul cu prioritate, trebuie să vă acorde prioritate de dreapta, deoarece dvs. îi veniți acestuia din partea dreaptă. Prin urmare, în această situație vă continuați drumul deoarece aveți prioritate față de celelalte vehicule.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0138.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0138.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 138; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă perspectiva unui șofer într-o intersecție nesemaforizată. Șoferul are în dreptul său indicatorul în formă de romb, galben în mijloc și cu margini albe, însoțit de un panou adițional, dreptunghiular, ce conține intersecția, îngroșând drumul care duce în stânga. În această situație, numai vehiculele care virează la stânga din această direcție au prioritate. Șoferul intenționează să vireze la stânga, deci este pe drumul prioritar. Vehiculul negru, care vine din dreapta, vrea să vireze la stânga și nu are niciun indicator. Autoturismul verde merge înainte, aflându-se pe drumul din stânga, fără indicator.","needsImageReview":true,"source":"RoDrive · ID 137 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"137","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_140.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0139","batch":"03","category":"Categoria B","question":"În care dintre situații oprirea este interzisă:","answers":["Pe străzile cu sens unic","În intersecțiile cu sens giratoriu","În dreptul indicatorului „parcarea interzisă\""],"correctIndices":[1],"correct":1,"explanation":"Oprirea este permisă pe drumurile pe care circulația se desfășoară în sens unic, oprirea fiind permisă chiar și pe partea stângă a acestor drumuri, dacă rămâne liberă cel puțin o bandă de circulație Oprirea voluntară a vehiculelor este interzisă în intersecții, inclusiv în cele cu circulație în sens giratoriu, precum și în zona de preselecție unde sunt aplicate marcaje continue, iar în lipsa acestor marcaje, oprirea este interzisă la o distanță mai mică de 25 metri de colțul intersecției. În dreptul indicatorului „Parcarea interzisă” nu se interzice oprirea.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0139.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0139.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 139; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 138 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-oprirea-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"138","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0140","batch":"03","category":"Categoria B","question":"Circulați în spatele unui vehicul cu tracțiune animală și constatați că acesta dorește să schimbe direcția de mers. Cum procedați?","answers":["Semnalizați sonor intenția de a-l depăși","Permiteți vehiculului efectuarea în siguranță a manevrei","Nu aveți nicio obligație"],"correctIndices":[1],"correct":1,"explanation":"Atunci când vehiculul din fața dumneavoastră semnalizează intenția de schimbare a direcției de mers, ca de exemplu un vehicul cu tracțiune animală al cărui conducător semnalizează intenția de a schimba direcția de mers, sunteți obligați să îi permiteți acestuia efectuarea manevrei în condiții de siguranță.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0140.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0140.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 140; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 139 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/circulati-in-spatele-unui-vehicul-cu-tractiune-animala-si-constatati-ca-acesta-doreste-sa-schimbe-directia-de-mers-cum-procedati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"139","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0141","batch":"03","category":"Categoria B","question":"Când constatați că aveți anumite probleme cu vederea, trebuie:","answers":["Să vă cumpărați ochelari de vedere cu caracteristici superioare","Să evitați conducerea autovehiculului până când sunteți consultat de medicul specialist, urmând să vă conformați sfaturilor acestuia","Să conduceți folosind lumina de drum chiar și în localități sau când din sens opus se apropie alte vehicule"],"correctIndices":[1],"correct":1,"explanation":"În acest caz, dacă vă cumpăraţi ochelari de vedere cu caracteristici superioare, trebuie să consultați un medic specialist. Prin urmare, varianta A este incorectă. Conducătorii de autovehicule trebuie să fie apţi din punct de vedere medical şi psihologic. Prin urmare, atunci când constataţi că aveţi anumite probleme cu vederea, trebuie să evitaţi conducerea autovehiculului până când sunteţi consultat de medicul specialist, urmând să vă conformaţi sfaturilor acestuia. Vă este interzis să conduceţi folosind lumina de drum când din sens opus se apropie alte vehicule la o distanță mai mică de 200 de metri, astfel îi deranjați pe ceilalți participanți la trafic. Prin urmare, varianta C este incorectă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0141.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0141.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 141; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 140 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-constatati-ca-aveti-anumite-probleme-cu-vederea-trebuie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"140","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0142","batch":"03","category":"Categoria B","question":"Cursa liberă a pedalei de frână, mai mică decât cea obișnuită, indică:","answers":["Blocarea pedalei de frână","Un joc insuficient între saboți și tamburi","Pierderi de lichid pe la garnituri"],"correctIndices":[1],"correct":1,"explanation":"Dacă jocul între saboți și tamburi este insuficient, sau mult mai mic decât în mod normal, saboții au nevoie de o distanță foarte scurtă pe care să o parcurgă până să apese pe tamburi la acționarea pedalei de frână. Prin urmare, cursa liberă a pedalei de frână, mai mică decât cea obișnuită, indică un joc insuficient între saboți (sau plăcuțe) și tamburi (sau discuri). Dacă pedala de frână ar fi blocată, saboții ar presa permanent pe tamburi și s-ar merge cu frâna blocată/acționată. Prin urmare, roțile se vor bloca, sau acestea se vor roti greoi, dar ar duce supraîncălzirea frânelor. În cazul în care s-ar pierde lichid din instalație, ar rămâne o cantitate mai mică de compresat la apăsarea pedalei, ceea ce ar permite o cursă mai lungă a pedalei de frână. Prin urmare, cursa pedalei ar fi mai lungă decât în mod obișnuit.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0142.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0142.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 142; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 141 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cursa-libera-a-pedalei-de-frana-mai-mica-decat-cea-obisnuita-indica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"141","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0143","batch":"03","category":"Categoria B","question":"Ce se înțelege prin conducere ecologică a unui autovehicul?","answers":["Obligația de a folosi în permanență carburant biodegradabil","Deplasări urbane cu bicicleta, pe jos sau cu alte mijloace care nu poluează atmosfera","Un ansamblu de măsuri comportamentale, de control sau de verificare a vehiculului, prin care se realizează o importantă economie de energie și protecția mediului"],"correctIndices":[2],"correct":2,"explanation":"Conducerea ecologica este ansamblul măsurilor comportamentale, de control sau verificare a vehiculului, care duc la un consum de carburant mai mic, protejând astfel mediul înconjurător. Orice măsură luată pentru a scădea consumul de combustibil se înscrie în conducerea ecologică. Sistemele auxiliare ale unui autovehicul precum și unul dintre cele mai cunoscute și folosite, aerul condiționat, au ca efect creșterea consumului de carburant și astfel autovehiculul poluează mai mult mediul înconjurător.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0143.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0143.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 143; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 142 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-se-intelege-prin-conducere-ecologica-a-unui-autovehicul","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"142","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0144","batch":"03","category":"Categoria B","question":"Precizați dacă posesorul unui permis de conducere categoria B are permisiunea de a conduce un autoturism cu remorcă:","answers":["Da, cu condiția ca acesta să aibă permis de cel puțin 3 ani","Da, dacă masa remorcii nu depășește 750 kg","Nu, deoarece pentru o astfel de remorcă este necesar un permis de conducere categoria be"],"correctIndices":[1],"correct":1,"explanation":"Posesorul unui permis de conducere categoria B are permisiunea de a conduce un autoturism cu remorcă, dacă masa totală maximă autorizată a remorcii nu depășește 750 kg.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0144.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0144.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 144; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 143 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-daca-posesorul-unui-permis-de-conducere-categoria-b-are-permisiunea-de-a-conduce-un-autoturism-cu-remorca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"143","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0145","batch":"03","category":"Categoria B","question":"Conducătorul de vehicul are obligația de a ceda trecerea la schimbarea direcției de mers spre stânga, în timp ce semnalul verde este în funcțiune?","answers":["Nu, deoarece semnalul verde îi conferă prioritate de trecere","Nu, cu excepția cazului în care, din sens opus, se apropie un mijloc de transport public","Da, atât vehiculelor care circulă din sens opus, cât și pietonilor care traversează strada pe care acesta urmează să intre, pe sensul său de mers"],"correctIndices":[2],"correct":2,"explanation":"Atunci când virați către stânga într-o intersecție la semnalul de culoare verde al semaforului care vi se adresează, aveți obligația să acordați prioritate de trecere vehiculelor care circulă din sens opus, deoarece acestea întâlnesc, ca și dvs., semnalul de culoare verde al semaforului, situație în care se aplică regula priorității de dreapta și trebuie să le acordați prioritate de trecere deoarece în timpul virajului spre stânga acestea vin din partea dreaptă a dvs.. De asemenea, aveți obligația de a acorda prioritate de trecere și pietonilor care traversează regulamentar strada pe care doriți să intrați, atunci când aceștia se află pe sensul dumneavoastră de mers.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0145.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0145.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 145; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 144 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-de-vehicul-are-obligatia-de-a-ceda-trecerea-la-schimbarea-directiei-de-mers-spre-stanga-in-timp-ce-semnalul-verde-este-in-funct","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"144","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0146","batch":"03","category":"Categoria B","question":"Oprirea voluntară a unui vehicul este interzisă:","answers":["Pe drumurile cu un singur sens de circulație","Pe drumurile cu o lățime mai mică de 6 m","În locurile unde s-ar împiedica observarea unui indicator sau a unui semnal luminos"],"correctIndices":[2],"correct":2,"explanation":"Pe drumurile pe care circulația se desfășoară într-un singur sens oprirea este permisă, este permisă chiar și pe partea stângă, dacă rămâne liberă cel puțin o bandă de circulație. Oprirea este permisă și pe drumurile cu o lățime mai mică de 6 metri, pe aceste drumuri fiind interzisă staționarea, nu și oprirea. Oprirea voluntară a vehiculelor este interzisă în locurile unde s-ar împiedica observarea unui indicator sau semnal luminos.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0146.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0146.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 146; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 145 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-voluntara-a-unui-vehicul-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"145","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0147","batch":"03","category":"Categoria B","question":"Conducătorul unui vehicul implicat într-un accident de circulație, din care au rezultat numai pagube materiale, este obligat să se supună recoltării probelor biologice, dacă aerul expirat, testat cu un aparat autorizat, arată o concentrație:","answers":["Mai mică de 0,40 mg/l alcool pur","Mai mare de 0,80 mg/l alcool pur","Mai mare de 0,40 mg/l alcool pur"],"correctIndices":[2],"correct":2,"explanation":"Conducătorul unui vehicul implicat într-un accident de circulație, din care au rezultat numai pagube materiale (mai exact într-un accident fără victime), este obligat să se supună testării aerului expirat în vederea stabilirii alcoolemiei ori a consumului de substanțe psihoactive. În situația în care, în urma testării se arată o concentrațiemai mare de 0,40 mg/lalcool pur în aerul expirat sau se indică prezența în organism a substanțelor psihoactive,conducătorii de vehicule sunt obligați să se supună recoltării mostrelor biologice.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0147.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0147.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 147; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 146 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorul-unui-vehicul-implicat-intr-un-accident-de-circulatie-din-care-au-rezultat-numai-pagube-materiale-este-obligat-sa-se-supuna-reco","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"146","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0148","batch":"03","category":"Categoria B","question":"Indicatorul din imagine semnifică:","answers":["„circulație în ambele sensuri“","„circulația interzisă în ambele sensuri“","„prioritate pentru circulația din sens invers“"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul din imagine se numește “Circulație în ambele sensuri”, acesta se găsește instalat la ieșirea de pe un drum public cu sens unic și are rolul de a atenționa conducătorul auto că pe sectorul de drum urmator circulația se desfășoară în ambele sensuri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0148.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0148.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 148; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum urban cu un indicator triunghiular cu margini roșii, cu două săgeți negre. Prima săgeată, din stânga, este îndreptată în jos, iar cea din dreapta este îndreptată în sus. Indicatorul avertizează faptul că pe drumul respectiv circulația se face în ambele sensuri.","needsImageReview":true,"source":"RoDrive · ID 147 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/indicatorul-din-imagine-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"147","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_150.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0149","batch":"03","category":"Categoria B","question":"Cum veți proceda la întâlnirea indicatorului „Oprire“?","answers":["Opriți în locul în care aveți vizibilitatea cea mai bună pentru a vă asigura și vă continuați deplasarea numai dacă pe drumul transversal nu circulă alt vehicul","Reduceți viteza până la limita evitării oricărui pericol, după care traversați intersecția","Reduceți viteza și pătrundeți în intersecție dacă nu circulă alt vehicul din partea dreaptă"],"correctIndices":[0],"correct":0,"explanation":"La întâlnirea indicatorului “Oprire” trebuie să opriți în locul cu vizibilitate maximă, putând trece de indicator, dar fără a depăși colțul intersecției, și stând pe loc să acordați prioritate tuturor vehiculelor care circulă pe drumul prioritar. Atenție! Oprirea este obligatorie indiferent dacă pe drumul cu prioritate circulă sau nu vehicule în acel moment.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0149.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0149.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 149; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicatorul 'STOP'.","needsImageReview":true,"source":"RoDrive · ID 148 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-la-intalnirea-indicatorului-oprire","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"148","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_151.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0150","batch":"03","category":"Categoria B","question":"Cum procedați dacă vă aflați la volanul autoturismului?","answers":["Acordați prioritate tramvaiului","Acordați prioritate autobuzului","Acordați prioritate ambelor vehicule, fiind din serviciul de transport public de persoane"],"correctIndices":[1],"correct":1,"explanation":"În această situație vă aflați la volanul autoturismului roșu și intenționați să virați către stânga în această intersecție, dirijată prin indicatoare de reglementare de prioritate. Dumneavoastră și autobuzul circulați pe drumul cu prioritate, tramvaiul fiind obligat să vă acorde prioritate de trecere deoarece vine de pe un drum fără prioritate, întâlnind indicatorul “Cedează trecerea”. Însă dumneavoastră virând către stânga, trebuie să îi acordați autobuzului prioritate de trecere, deoarece schimbând direcția de mers către stânga pierdeți prioritatea față de acesta. Deci în această situație trebuie să îi acordați prioritate autobuzului, iar ordinea de trecere este următoarea: autobuzul, după care autoturismul roșu iar ultimul prin această intersecție va trece tramvaiul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0150.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0150.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 150; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea reprezintă o intersecție văzută de sus, în care sunt implicate trei vehicule: un autoturism roșu care vine de jos, un tramvai care vine din dreapta și un autobuz galben care vine de sus. Drumurile din stânga și din dreapta sunt semnalizate cu indicatoare triunghiulare cu margini roșii, 'Cedează trecerea'. Autoturismul dorește să vireze la stânga, tramvaiul circulă înainte, iar autobuzul circulă înainte.","needsImageReview":true,"source":"RoDrive · ID 149 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-daca-va-aflati-la-volanul-autoturismului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"149","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_152.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
